/**
 * Wire routing integrity (rt2): the canonical router reproduces, bit for bit, the golden routes of
 * seeded random benches of 5 to 80 automatic wires (sparse, dense, with an ESP32 board), as opened
 * and after one part is moved. Generated by the router of fae6a3c; REGENERATED on purpose in
 * Sprint 20 round 2 (s20r: wires of one node share runs instead of crossing; metrics over the 50
 * documents, old -> new: bends 2569 -> 1774, hops 703 -> 419, same-node crossings 609 -> 37,
 * length 384820 -> 295660, length through bodies 752 -> 0, near-body length 53290 -> 55338,
 * terminal keep-out entries 0 -> 0).
 * REGENERATED again in Sprint 21 (s21r, owner screenshot: wires on a part's outline, half hidden
 * under its symbol): a step along a body's outline costs 0.75 bend (the first step out of the
 * wire's own terminal exempt), and a hop whose short shapes all run along an outline also tries
 * them from one grid step straight out of its ends. Over the 50 documents (s21r-golden-*.txt),
 * old -> new: outline length 32988 -> 30974, same-node crossings 37 -> 30, hops 419 -> 410,
 * bridges 456 -> 440, bends 1774 -> 1815, length 295660 -> 299620, body 0 -> 0, different-node
 * touches / overlaps 0 -> 0.
 * The guard for every performance change: determinism means the same document always gives the
 * same routes, so a faster router must give exactly the old ones.
 */
import { readFileSync } from 'node:fs';
import { describe, expect, it } from 'vitest';
import { routeAutomatic } from '../src/ui/routing.js';
import { GOLDEN_CASES, caseKey, goldenDocs, routesHash } from './support/routingGolden.js';

const golden = JSON.parse(
  readFileSync(new URL('./fixtures/rt2-canonical-routes.json', import.meta.url), 'utf8'),
) as Record<string, { open: string; moved: string }>;

describe('canonical routes: golden (rt2)', () => {
  it('every golden bench routes exactly as the golden fixture (opened and after a move)', () => {
    expect(Object.keys(golden).sort()).toEqual(GOLDEN_CASES.map(caseKey).sort());
    for (const c of GOLDEN_CASES) {
      const { open, moved } = goldenDocs(c, routeAutomatic);
      expect([routesHash(open), routesHash(moved)], caseKey(c)).toEqual([
        golden[caseKey(c)]!.open,
        golden[caseKey(c)]!.moved,
      ]);
    }
  });
});
